    font-weight: 700;
}

.description-icon {
    margin-inline-start: auto;
    width: 30px;
    height: 30px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 9px;
    cursor: pointer;
    opacity: 0.7;
    transition:
        opacity 0.15s ease,
        background-color 0.15s ease,
        transform 0.15s ease;

    mat-icon {
        width: 18px;
        height: 18px;
        font-size: 18px;
    }

    &:hover {
        opacity: 1;
        background: color-mix(in srgb, currentColor 10%, transparent);
        transform: translateY(-1px);
    }
}
